import { validateCatalog } from './validate-template-catalog.mjs';
import { readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
const contract = JSON.parse(readFileSync(new URL('../bridge-contract.json', import.meta.url), 'utf8'));
writeFileSync(new URL('../dsh-tool-lamber/src/contract.generated.ts', import.meta.url),
  '// Generated by scripts/build-contract.mjs; edit bridge-contract.json.\n' +
  `export const BRIDGE_CONTRACT = ${JSON.stringify(contract)} as const;\n`);

// Traverse all template records. Only text entries become writable schema properties.
const catalog = JSON.parse(readFileSync(new URL('../../src-ui/src/lib/templateCompletion/catalog.json', import.meta.url), 'utf8'));
validateCatalog(catalog);
const ids = new Set(), names = new Set();
const kinds = new Set(['text','derived','check','list','image']);
for (const t of catalog.templates) {
  if (!t.id || !t.name || ids.has(t.id) || names.has(t.name) || !['.docx','.xlsx','.pptx'].includes(t.suffix)) throw new Error('Invalid/duplicate template identity');
  ids.add(t.id); names.add(t.name);
  if (t.excludedReason && t.fields.length) throw new Error('Excluded templates cannot contain fields');
  const keys = new Set();
  for (const f of t.fields) {
    if (!f.key || !f.label || !kinds.has(f.kind) || keys.has(f.key)) throw new Error(`Invalid/duplicate field in ${t.id}`);
    keys.add(f.key);
    if (f.stateKey && (f.kind !== 'text' || !/^[a-zA-Z][a-zA-Z0-9]*$/.test(f.stateKey))) throw new Error('Invalid root text state key');
    if (f.kind === 'list' && (!Array.isArray(f.columns) || !f.columns.length)) throw new Error('List requires safe read columns');
    if (f.kind === 'text' && /(?:amount|tax|discount|npv|years|total_cost|summary_metrics)/i.test(f.key)) throw new Error('Financial fields cannot be text-writable');
  }
}
const grouped = Object.fromEntries(catalog.templates.filter(t => !t.excludedReason).map(t => [t.id,
  Object.fromEntries(t.fields.filter(f => f.kind === 'text').map(f => [f.key, {type:'string',description:`${t.name}：${f.label}`}]))]));
// Data stays JSON, so adding a template changes no generated TypeScript either.
for (const folder of ['src','lib']) {
  const base = new URL(`../dsh-tool-lamber/${folder}/`, import.meta.url);
  mkdirSync(base,{recursive:true});
  writeFileSync(new URL('templateCatalog.generated.json',base),JSON.stringify(catalog));
  writeFileSync(new URL('templateFields.generated.json',base),JSON.stringify(grouped));
}
writeFileSync(new URL('../dsh-tool-lamber/src/templateFields.generated.ts', import.meta.url), `// Generated adapter; data lives in JSON.\nimport {readFileSync} from 'node:fs';\ntype TextSchema = {type:'string';description:string};\nexport const templateTextFieldsByTemplate = JSON.parse(readFileSync(new URL('./templateFields.generated.json',import.meta.url),'utf8')) as Record<string,Record<string,TextSchema>>;\nexport const templateTextFields: Record<string,TextSchema> = Object.assign({},...Object.values(templateTextFieldsByTemplate));\n`);
// Compile the production pure function itself; do not maintain a second completion algorithm.
const source = readFileSync(new URL('../../src-ui/src/lib/templateCompletion/catalog.ts', import.meta.url), 'utf8');
writeFileSync(new URL('../dsh-tool-lamber/src/catalogCompletion.generated.ts', import.meta.url),
  '// Generated from the UI pure function; edit catalog.ts.\n' + source.replace("import catalogData from './catalog.json';", "import {readFileSync} from 'node:fs';\nconst catalogData = JSON.parse(readFileSync(new URL('./templateCatalog.generated.json',import.meta.url),'utf8'));"));
for (const name of ['src/demandCompletion.generated.ts','lib/demandCompletion.generated.js','lib/demandCompletion.generated.d.ts']) rmSync(new URL(`../dsh-tool-lamber/${name}`,import.meta.url),{force:true});
